package com.google.gson.stream;

import com.google.gson.internal.JsonReaderInternalAccess;
import com.google.gson.internal.bind.JsonTreeReader;
import java.io.*;
import java.io.Closeable;
import java.io.EOFException;
import java.io.IOException;
import java.io.Reader;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.junit.runners.JUnit4;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertThrows;

@RunWith(JUnit4.class)
public class JsonReader_nextInt_TriageGen2Test {

    private JsonReader reader;
    private JsonReader readerWithPeekedNone;

    @Before
    public void setUp() throws IOException {
        reader = new JsonReader(new StringReader("{\"key\":123}"));
        readerWithPeekedNone = new JsonReader(new StringReader("{\"key\":123}"));
        readerWithPeekedNone.peeked = PEEKED_NONE;
    }

    @Test
    public void testNextInt_Normal() throws IOException {
        reader.beginObject();
        reader.nextName();
        assertEquals(123, reader.nextInt());
    }

    @Test
    public void testNextInt_PeekedNone() throws IOException {
        assertEquals(123, readerWithPeekedNone.nextInt());
    }

    @Test
    public void testNextInt_PeekedLong() throws IOException {
        readerWithPeekedNone.peeked = PEEKED_LONG;
        readerWithPeekedNone.peekedLong = 123.0;
        assertEquals(123, readerWithPeekedNone.nextInt());
    }

    @Test
    public void testNextInt_PeekedNumber() throws IOException {
        readerWithPeekedNone.peeked = PEEKED_NUMBER;
        readerWithPeekedNone.peekedString = "123";
        assertEquals(123, readerWithPeekedNone.nextInt());
    }

    @Test
    public void testNextInt_PeekedSingleQuoted() throws IOException {
        readerWithPeekedNone.peeked = PEEKED_SINGLE_QUOTED;
        readerWithPeekedNone.peekedString = "\"123\"";
        assertEquals(123, readerWithPeekedNone.nextInt());
    }

    @Test
    public void testNextInt_PeekedDoubleQuoted() throws IOException {
        readerWithPeekedNone.peeked = PEEKED_DOUBLE_QUOTED;
        readerWithPeekedNone.peekedString = "\"123\"";
        assertEquals(123, readerWithPeekedNone.nextInt());
    }

    @Test
    public void testNextInt_ParseAsDouble() throws IOException {
        readerWithPeekedNone.peeked = PEEKED_BUFFERED;
        readerWithPeekedNone.peekedString = "123.45";
        assertEquals(123, readerWithPeekedNone.nextInt());
    }

    @Test
    public void testNextInt_ParseAsDouble_LostPrecision() throws IOException {
        readerWithPeekedNone.peeked = PEEKED_BUFFERED;
        readerWithPeekedNone.peekedString = "123.4567890123";
        assertThrows(NumberFormatException.class, () -> readerWithPeekedNone.nextInt());
    }

    @Test
    public void testNextInt_IllegalState() throws IOException {
        readerWithPeekedNone.peeked = PEEKED_SINGLE_QUOTED;
        readerWithPeekedNone.peekedString = "\"abc\"";
        assertThrows(IllegalStateException.class, () -> readerWithPeekedNone.nextInt());
    }
}
